--
-- Table structure for table `comments`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `comments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `post_id` bigint unsigned NOT NULL COMMENT '帖子ID',
  `parent_id` bigint unsigned DEFAULT NULL COMMENT '父评论ID（楼中楼回复）',
  `author_id` bigint unsigned NOT NULL COMMENT '评论作者ID',
  `content` text NOT NULL COMMENT '评论内容',
  `images` json DEFAULT NULL COMMENT '评论图片URL JSON数组',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本号（Task 2.1.1）',
  `owner_circle_path` varchar(256) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_comments_post_id` (`post_id`),
  KEY `idx_comments_author_id` (`author_id`),
  KEY `idx_comments_created_at` (`created_at`),
