--
-- Table structure for table `post_likes`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `post_likes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL COMMENT '点赞用户ID',
  `post_id` bigint unsigned NOT NULL COMMENT '被点赞帖子ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '点赞时间',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本号（Task 2.1.1）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_post_likes_user_post` (`user_id`,`post_id`),
  KEY `idx_post_likes_user` (`user_id`),
  KEY `idx_post_likes_post` (`post_id`),
  KEY `idx_post_likes_user_created_at` (`user_id`,`created_at`),
  KEY `idx_post_likes_post_created` (`post_id`,`created_at`),
  CONSTRAINT `fk_post_likes_post` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_post_likes_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=157 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='帖子点赞记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

