--
-- Table structure for table `campus_topics`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `campus_topics` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint unsigned NOT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'course/club/activity/study/life/alumni',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci,
  `images` json DEFAULT NULL,
  `author_id` bigint unsigned NOT NULL,
  `reply_count` int NOT NULL DEFAULT '0',
  `view_count` int NOT NULL DEFAULT '0',
  `is_anonymous` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本号（Task 2.1.1）',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '话题状态: active/deleted/hidden',
  `audit_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'approved' COMMENT '审核状态: pending/approved/rejected',
  `audit_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核备注（拒绝原因等）',
  `auditor_id` bigint unsigned DEFAULT NULL COMMENT '审核人用户 ID',
  `audited_at` datetime DEFAULT NULL COMMENT '审核时间',
  `tags` json DEFAULT NULL COMMENT '话题标签数组（最多 5 个，每个 ≤20 字符）',
  `owner_circle_path` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_school_category` (`school_id`,`category`),
  KEY `idx_school_created` (`school_id`,`created_at` DESC),
  KEY `idx_author` (`author_id`),
  KEY `idx_campus_topics_school_cat_created` (`school_id`,`category`,`created_at`),
  KEY `idx_campus_topics_status` (`status`),
  KEY `idx_campus_topics_audit_status` (`audit_status`),
  CONSTRAINT `fk_campus_topics_author` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=353 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `campus_topics`
--

LOCK TABLES `campus_topics` WRITE;
/*!40000 ALTER TABLE `campus_topics` DISABLE KEYS */;
INSERT INTO `campus_topics` VALUES (1,9,'life_service','校园快递代收点地图','整理了一份上海交通大学各快递代收点分布图，菜鸟驿站、顺丰点、京东点都标注了位置和营业时间，新生同学建议收藏！',NULL,20082,3,264,0,'2026-08-25 12:16:10','2026-08-26 12:16:10',0,'active','approved',NULL,NULL,NULL,NULL,NULL),(2,9,'campus_activity','春季运动会志愿者招募','上海交通大学春季运动会需要三十名志愿者，主要负责检录和后勤，有志愿时长和纪念品。报名截止本周五，名额有限先到先得！',NULL,20082,9,205,0,'2026-08-19 12:16:10','2026-08-26 12:16:10',0,'active','approved',NULL,NULL,NULL,NULL,NULL),(3,9,'study_help','英语四六级备考互助','四六级考试临近，建了一个上海交通大学备考互助群，每天打卡背单词、互改作文。想一起上岸的同学滴滴我！',NULL,20082,7,88,0,'2026-08-24 12:16:10','2026-08-26 12:16:10',0,'active','approved',NULL,NULL,NULL,NULL,NULL),(4,9,'alumni_news','校友企业宣讲会预告','下周三上海交通大学校友企业专场宣讲会将在报告厅举行，多家知名企业HR到场，还有内推名额。建议大三大四同学提前准备好简历。',NULL,20082,4,142,0,'2026-08-20 12:16:10','2026-08-26 12:16:10',0,'active','approved',NULL,NULL,NULL,NULL,NULL),(5,9,'life_service','食堂新窗口测评','上海交通大学二食堂新开的窗口去试过了，麻辣香锅分量很足，价格也比外面实惠。二楼的面包房现烤的可颂也不错，推荐！',NULL,20082,6,176,0,'2026-08-21 12:16:10','2026-08-26 12:16:10',0,'active','approved',NULL,NULL,NULL,NULL,NULL),(6,9,'course_exchange','高数期中复习资料分享','整理了上海交通大学高数期中考试的复习要点和历年真题，需要的同学评论区留言，也可以私信我，免费分享给大家，祝考试顺利！',NULL,20082,12,320,0,'2026-08-22 12:16:10','2026-08-26 12:16:10',0,'active','approved',NULL,NULL,NULL,NULL,NULL),(7,9,'campus_activity','校园文化节周末开幕','本周末上海交通大学校园文化节开幕，现场有社团路演、美食集市和灯光秀，听说还有神秘嘉宾。欢迎大家来玩，记得穿得美美的拍照打卡！',NULL,20082,8,210,0,'2026-08-23 12:16:10','2026-08-26 12:16:10',0,'active','approved',NULL,NULL,NULL,NULL,NULL),(8,9,'club_recruitment','摄影社春季招新','摄影社春季招新开始啦！零基础也可以加入，有学长学姐手把手带拍，定期组织校园外拍和棚拍活动。报名地点：上海交通大学学生活动中心二楼。',NULL,20082,5,98,0,'2026-08-25 12:16:10','2026-08-26 12:16:10',0,'active','approved',NULL,NULL,NULL,NULL,NULL),(9,9,'study_help','考研自习室占座攻略','上海交通大学图书馆考研专区座位一直很紧张，分享几个实测有效的小技巧：早起十分钟、错峰去负一层、提前一天在预约系统锁座。祝大家一战成硕！',NULL,20082,3,156,0,'2026-08-24 12:16:10','2026-08-26 12:16:10',0,'active','approved',NULL,NULL,NULL,NULL,NULL),(10,5,'life_service','校园快递代收点地图','整理了一份东南大学各快递代收点分布图，菜鸟驿站、顺丰点、京东点都标注了位置和营业时间，新生同学建议收藏！',NULL,10013,3,264,0,'2026-08-25 