--
-- Table structure for table `campus_topic_replies`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `campus_topic_replies` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `topic_id` bigint unsigned NOT NULL,
  `author_id` bigint unsigned NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_anonymous` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本号（Task 2.1.1）',
  PRIMARY KEY (`id`),
  KEY `idx_topic` (`topic_id`),
  KEY `fk_campus_topic_replies_author` (`author_id`),
  KEY `idx_campus_topic_replies_topic_created` (`topic_id`,`created_at`),
  CONSTRAINT `campus_topic_replies_ibfk_1` FOREIGN KEY (`topic_id`) REFERENCES `campus_topics` (`id`),
  CONSTRAINT `fk_campus_topic_replies_author` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

