--
-- Table structure for table `users`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `openid` varchar(128) NOT NULL,
  `nickname` varchar(64) NOT NULL DEFAULT '新同学',
  `avatar_url` varchar(512) DEFAULT NULL,
  `bio` text,
  `grade_label` varchar(32) DEFAULT NULL,
  `pronouns` varchar(32) DEFAULT NULL,
  `phone` varchar(64) DEFAULT NULL COMMENT '手机号（AES-GCM 密文或历史明文）',
  `profile_completion` int NOT NULL DEFAULT '0',
  `interest_tags` json DEFAULT NULL,
  `following_count` int NOT NULL DEFAULT '0',
  `followers_count` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `role` varchar(16) NOT NULL DEFAULT 'USER' COMMENT '鐢ㄦ埛瑙掕壊: USER/ADMIN',
  `circle_path` varchar(256) DEFAULT NULL,
  `campus_name` varchar(128) DEFAULT NULL COMMENT '管理员管辖校区名（NULL=全局管理员，非空=校区管理员）',
  `password` varchar(100) DEFAULT NULL COMMENT '密码 BCrypt 哈希（管理员与密码登录用户使用，微信登录用户为 NULL）',
  `status` varchar(16) NOT NULL DEFAULT 'active' COMMENT '账号状态: active/disabled',
  `auto_renew_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'VIP 自动续费开关 0关闭 1开启',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本号（Task 2.1.1）',
  `birth_date` date DEFAULT NULL COMMENT '出生日期（未成年人保护，注册必填；存量用户可补填）',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '纬度（gcj02 坐标系，精度 6 位小数）',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '经度（gcj02 坐标系，精度 6 位小数）',
  `geo_updated_at` timestamp NULL DEFAULT NULL COMMENT '最近一次坐标上报时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_openid` (`openid`),
  UNIQUE KEY `uk_users_phone` (`phone`),
  KEY `idx_users_profile_completion` (`profile_completion`),
  KEY `idx_users_status` (`status`),
  KEY `idx_users_phone` (`phone`),
  KEY `idx_users_created_at` (`created_at`),
  KEY `idx_users_role` (`role`),
  KEY `idx_users_geo` (`latitude`,`longitude`)
) ENGINE=InnoDB AUTO_INCREMENT=100177 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

